#!/usr/bin/env node
// Build-time (and offline): emits the grammar registry for a selected language
// subset from the in-tree vendored files. No network, reads only --vendor-dir.
// Invoked by the Android CMake configure step and the iOS podspec, and by
// vendor-grammars.mjs to refresh the committed default set.
//
//   node vendor/gen-registry.mjs --vendor-dir <dir> --languages a,b,c --out <dir>
//
// Writes <out>/generated_queries.h and <out>/generated_registry.cpp referencing
// only the selected grammars, so the link step stays valid no matter how many
// grammars are vendored. `; inherits:` directives are resolved by inlining the
// parent grammar's highlights (parents come first, child overrides).

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));

const LOG_PREFIX = '[react-native-enriched-markdown]';
const log = (message) => console.log(`${LOG_PREFIX} ${message}`);
const warn = (message) => console.warn(`${LOG_PREFIX} ${message}`);
const fail = (message) => {
  console.error(`${LOG_PREFIX} ${message}`);
  process.exit(1);
};

function parseArgs(argv) {
  const args = { vendorDir: null, languages: [], out: null, manifest: path.join(here, 'grammar-versions.json') };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--vendor-dir') args.vendorDir = argv[++i];
    else if (a === '--languages') args.languages = argv[++i].split(',').map((s) => s.trim()).filter(Boolean);
    else if (a === '--out') args.out = argv[++i];
    else if (a === '--manifest') args.manifest = argv[++i];
  }
  if (!args.vendorDir || !args.out) {
    fail('usage: --vendor-dir <dir> --languages a,b --out <dir>');
  }
  return args;
}

function identifier(id) {
  return id.replace(/[^A-Za-z0-9]/g, '_');
}

function grammarFunction(id, manifest) {
  const spec = manifest.grammars?.[id];
  return spec?.function ?? `tree_sitter_${identifier(id)}`;
}

function highlightsPath(vendorDir, id) {
  return path.join(vendorDir, 'grammars', id, 'highlights.scm');
}

const INHERITS_RE = /^[ \t]*;+[ \t]*inherits[ \t]*:[ \t]*([^\n]+)$/m;

// Reads a grammar's highlights.scm and inlines any `; inherits:` parents that
// are also vendored. Cycle-guarded; a missing parent is skipped with a warning.
function resolveHighlights(vendorDir, id, seen = new Set()) {
  const file = highlightsPath(vendorDir, id);
  if (!fs.existsSync(file)) {
    fail(`missing vendored highlights for '${id}': ${file}`);
  }
  if (seen.has(id)) return '';
  seen.add(id);

  const raw = fs.readFileSync(file, 'utf8');
  const match = raw.match(INHERITS_RE);
  let inherited = '';
  if (match) {
    for (const parent of match[1].split(',').map((s) => s.trim()).filter(Boolean)) {
      if (fs.existsSync(highlightsPath(vendorDir, parent))) {
        inherited += resolveHighlights(vendorDir, parent, seen) + '\n';
      } else {
        warn(`${id} inherits '${parent}' which is not vendored; skipping inheritance`);
      }
    }
  }
  const body = raw.replace(INHERITS_RE, '');
  return inherited + body;
}

function toCStringLines(text) {
  const lines = text.split('\n');
  return lines
    .map((line, i) => {
      // Escape backslashes, quotes, and every '?' so sequences like "??=" in a
      // query never form a C trigraph.
      const escaped = line.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\?/g, '\\?');
      const newline = i < lines.length - 1 ? '\\n' : '';
      return `    "${escaped}${newline}"`;
    })
    .join('\n');
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const manifest = JSON.parse(fs.readFileSync(args.manifest, 'utf8'));
  fs.mkdirSync(args.out, { recursive: true });

  const entries = args.languages.map((id) => ({
    id,
    ident: identifier(id),
    fn: grammarFunction(id, manifest),
    query: resolveHighlights(args.vendorDir, id),
  }));

  const queriesHeader =
    '#pragma once\n' +
    '// Generated by vendor/gen-registry.mjs. Do not edit.\n\n' +
    'namespace Markdown {\n\n' +
    entries
      .map((e) => `static const char kHighlightsQuery_${e.ident}[] =\n${toCStringLines(e.query)};\n`)
      .join('\n') +
    '\n} // namespace Markdown\n';

  const header =
    '// Generated by vendor/gen-registry.mjs. Do not edit.\n\n' +
    '#include "HighlightGrammars.hpp"\n' +
    '#include "generated_queries.h"\n\n' +
    '#include <cstring>\n\n';

  let registryCpp;
  if (entries.length === 0) {
    registryCpp =
      header +
      'namespace Markdown {\n\n' +
      'const GrammarEntry *findGrammar(const char * /*canonicalId*/) {\n  return nullptr;\n}\n\n' +
      '} // namespace Markdown\n';
  } else {
    registryCpp =
      header +
      'extern "C" {\n' +
      entries.map((e) => `const TSLanguage *${e.fn}(void);`).join('\n') +
      '\n}\n\n' +
      'namespace Markdown {\nnamespace {\n\n' +
      'constexpr GrammarEntry kGrammars[] = {\n' +
      entries.map((e) => `    {"${e.id}", ${e.fn}, kHighlightsQuery_${e.ident}},`).join('\n') +
      '\n};\n\n' +
      '} // namespace\n\n' +
      'const GrammarEntry *findGrammar(const char *canonicalId) {\n' +
      '  if (canonicalId == nullptr) {\n    return nullptr;\n  }\n' +
      '  for (const GrammarEntry &entry : kGrammars) {\n' +
      '    if (std::strcmp(entry.canonicalId, canonicalId) == 0) {\n      return &entry;\n    }\n  }\n' +
      '  return nullptr;\n}\n\n' +
      '} // namespace Markdown\n';
  }

  fs.writeFileSync(path.join(args.out, 'generated_queries.h'), queriesHeader);
  fs.writeFileSync(path.join(args.out, 'generated_registry.cpp'), registryCpp);
  log(`wrote ${entries.length} grammar(s) to ${args.out}`);
}

main();
